{"type":"item.completed","item":{"id":"item_22","type":"command_execution","command":"/bin/bash -lc 'git diff --cached MERGE_HEAD -- MIPStarRE blueprint'","aggregated_output":"* Unmerged path MIPStarRE/QPBT.lean\ndiff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree.lean\nindex 6d59ead3..f00335d6 100644\n--- a/MIPStarRE/QPBT/Combining/DirectLowDegree.lean\n+++ b/MIPStarRE/QPBT/Combining/DirectLowDegree.lean\n@@ -5,6 +5,7 @@ import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.Consistency\n import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.LineResampling\n import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.Strategy\n import MIPStarRE.QPBT.Combining.DirectLowDegree.GameValue\n+import MIPStarRE.QPBT.Combining.DirectLowDegree.RejectionBounds\n import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.PassConversion\n import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.SeedFiberValue\n import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.Error\n@@ -25,6 +26,8 @@ import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.Combining.Simultaneous\n import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.Combining.Error\n import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.PointAgreement\n import MIPStarRE.QPBT.Combining.DirectLowDegree.SeedIndexedSoundness\n+import MIPStarRE.QPBT.Combining.DirectLowDegree.ResampledCoefficientConsistency\n+import MIPStarRE.QPBT.Combining.DirectLowDegree.ExtendedCoefficientLoss\n \n /-!\n # The directly indexed low-degree game\ndiff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree/ExtendedCoefficientLoss.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree/ExtendedCoefficientLoss.lean\nnew file mode 100644\nindex 00000000..0b9480f3\n--- /dev/null\n+++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/ExtendedCoefficientLoss.lean\n@@ -0,0 +1,45 @@\n+import MIPStarRE.QPBT.Combining.DirectLowDegree.ResampledCoefficientConsistency\n+\n+/-!\n+# Extended direct coefficient-collision loss\n+\n+This module compares the sum of the axis and diagonal coefficient-collision\n+losses at the extended directly indexed parameters with the original `m*d/q`\n+ratio.\n+\n+## References\n+\n+- `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:331-344`\n+- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1595-1603`\n+-/\n+\n+namespace MIPStarRE.QPBT\n+\n+/-- The axis loss `d/q` plus the diagonal loss `(2m+2)d/q` at the extended\n+direct parameters is at most five times the original loss `md/q`.\n+\n+This is a Lean-only scalar auxiliary for combining the two coefficient-POVM\n+consistency estimates. It uses only admissibility of the original parameters. -/\n+theorem extendedDirectLd_coefficientCollisionLoss_le_five_mul\n+    (P : AdmissibleParams) :\n+    ((P.extendedDirectLd.d : ℝ) +\n+        (P.extendedDirectLd.m * P.extendedDirectLd.d : ℝ)) /\n+        (P.extendedDirectLd.q : ℝ) ≤\n+      5 * ((P.m * P.d : ℝ) / (P.q : ℝ)) := by\n+  have hm : (1 : ℝ) ≤ (P.m : ℝ) := by\n+    exact_mod_cast P.one_le_m\n+  have hqNat : 0 < P.q := by\n+    rcases P.hq with ⟨k, _, hk⟩\n+    rw [hk]\n+    exact Nat.pow_pos (by decide)\n+  have hq : (0 : ℝ) < (P.q : ℝ) := by\n+    exact_mod_cast hqNat\n+  change ((P.d : ℝ) + ((2 * P.m + 2 : ℕ) : ℝ) * (P.d : ℝ)) /\n+      (P.q : ℝ) ≤ 5 * ((P.m : ℝ) * (P.d : ℝ) / (P.q : ℝ))\n+  push_cast\n+  rw [show 5 * ((P.m : ℝ) * (P.d : ℝ) / (P.q : ℝ)) =\n+    (5 * ((P.m : ℝ) * (P.d : ℝ))) / (P.q : ℝ) by ring]\n+  apply (div_le_div_iff_of_pos_right hq).2\n+  nlinarith [show (0 : ℝ) ≤ (P.d : ℝ) by positivity]\n+\n+end MIPStarRE.QPBT\ndiff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree/Geometry.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree/Geometry.lean\nindex ba01f6cc..7a80d507 100644\n--- a/MIPStarRE/QPBT/Combining/DirectLowDegree/Geometry.lean\n+++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/Geometry.lean\n@@ -88,7 +88,7 @@ instance (D : DirectLdParams) : Nonempty (DirectLdSpace D) :=\n \n /-- Decompose a direct sample into its point and the remaining independent\n coordinates. -/\n-private def directLdSpacePointEquiv (D : DirectLdParams) :\n+def directLdSpacePointEquiv (D : DirectLdParams) :\n     DirectLdSpace D ≃\n       (Fin D.m → DirectScalarQ D) ×\n         (Fin D.m × (Fin D.m → DirectScalarQ D)) where\n@@ -142,6 +142,45 @@ inductive DirectLineDesc (D : DirectLdParams) where\n       (prefixZero : ∀ j : Fin D.m, j.val < index.val → direction j = 0)\n   deriving DecidableEq\n \n+/-! ## Finite direct-line carrier -/\n+\n+/-- A finite code for directly indexed lines, omitting only proof fields. -/\n+private abbrev DirectLineDescCode (D : DirectLdParams) :=\n+  ((Fin D.m → DirectScalarQ D) × Fin D.m) ⊕\n+    ((Fin D.m → DirectScalarQ D) × Fin D.m ×\n+      (Fin D.m → DirectScalarQ D))\n+\n+/-- Encode a directly indexed line by its tag and mathematical data. -/\n+private def directLineDescCode (D : DirectLdParams) :\n+    DirectLineDesc D → DirectLineDescCode D\n+  | .axis base index _ => .inl (base, index)\n+  | .diagonal base index direction _ _ => .inr (base, index, direction)\n+\n+/-- The direct-line code is injective by proof irrelevance. -/\n+private theorem directLineDescCode_injective (D : DirectLdParams) :\n+    Function.Injective (directLineDescCode D) := by\n+  intro line line' h\n+  cases line with\n+  | axis base index baseFixed =>\n+      cases line' with\n+      | axis base' index' baseFixed' =>\n+          simp only [directLineDescCode, Sum.inl.injEq, Prod.mk.injEq] at h\n+          rcases h with ⟨rfl, rfl⟩\n+          rfl\n+      | diagonal => simp [directLineDescCode] at h\n+  | diagonal base index direction baseFixed prefixZero =>\n+      cases line' with\n+      | axis => simp [directLineDescCode] at h\n+      | diagonal base' index' direction' baseFixed' prefixZero' =>\n+          simp only [directLineDescCode, Sum.inr.injEq, Prod.mk.injEq] at h\n+          rcases h with ⟨rfl, rfl, rfl⟩\n+          rfl\n+\n+/-- Directly indexed line descriptions form a finite type. -/\n+noncomputable instance directLineDescFintype (D : DirectLdParams) :\n+    Fintype (DirectLineDesc D) :=\n+  Fintype.ofInjective (directLineDescCode D) (directLineDescCode_injective D)\n+\n /-- The kind of a directly indexed line. -/\n def DirectLineDesc.kind {D : DirectLdParams} : DirectLineDesc D → LineKind\n   | .axis _ _ _ => .axis\ndiff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree/RejectionBounds.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree/RejectionBounds.lean\nnew file mode 100644\nindex 00000000..63ca6b54\n--- /dev/null\n+++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/RejectionBounds.lean\n@@ -0,0 +1,45 @@\n+import MIPStarRE.QPBT.Combining.DirectLowDegree.GameValue\n+\n+/-! # Probability bounds for the directly indexed low-degree game\n+\n+This module records two elementary probability bounds needed when a caller caps an\n+assembled direct-game rejection estimate by one. The results are formalization-only\n+support: they do not bound any individual game branch or prove a passing-value theorem.\n+\n+## References\n+\n+- `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:178-186`\n+- Parent issue #119 and arithmetic issue #333\n+-/\n+\n+namespace MIPStarRE.QPBT\n+\n+open MIPStarRE.LDT\n+\n+namespace Strategy\n+\n+/-- Every tensor-product strategy has nonnegative value. -/\n+theorem value_nonneg {G : Game} (S : Strategy G) : 0 ≤ S.value := by\n+  unfold value\n+  apply avgOver_nonneg\n+  intro questions\n+  apply Finset.sum_nonneg\n+  intro answerA _\n+  apply Finset.sum_nonneg\n+  intro answerB _\n+  split\n+  · exact outcomeWeight_nonneg S questions.1 questions.2 answerA answerB\n+  · exact le_rfl\n+\n+end Strategy\n+\n+/-- The total rejection probability of a directly indexed low-degree strategy is at\n+most one. This is the probability cap used by scalar error envelopes; it gives no\n+quantitative branch estimate. -/\n+theorem directLdRejectionProbability_le_one\n+    (D : DirectLdParams) (S : Strategy (directLdGame D)) :\n+    directLdRejectionProbability D S ≤ 1 := by\n+  rw [directLdRejectionProbability_eq_one_sub_value]\n+  linarith [S.value_nonneg]\n+\n+end MIPStarRE.QPBT\ndiff --git a/MIPStarRE/QPBT/Combining/DirectLowDegree/ResampledCoefficientConsistency.lean b/MIPStarRE/QPBT/Combining/DirectLowDegree/ResampledCoefficientConsistency.lean\nnew file mode 100644\nindex 00000000..67dadf75\n--- /dev/null\n+++ b/MIPStarRE/QPBT/Combining/DirectLowDegree/ResampledCoefficientConsistency.lean\n@@ -0,0 +1,237 @@\n+import MIPStarRE.QPBT.Combining.DirectLowDegree.CoefficientConsistency\n+import MIPStarRE.QPBT.Combining.DirectLowDegree.Transport.LineResampling\n+\n+/-!\n+# Resampled consistency of direct coefficient measurements\n+\n+This module reexpresses the consistency defect of uniformly evaluated direct\n+coefficient measurements over the original joint line-point distributions.\n+For a zero direction, the sampled point does not determine the affine\n+parameter, so the joint integrand retains the full uniform parameter average.\n+\n+## References\n+\n+- `references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:243-344`\n+- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1020-1116`\n+-/\n+\n+open scoped BigOperators MatrixOrder Matrix ComplexOrder\n+\n+namespace MIPStarRE.QPBT\n+\n+open MIPStarRE.LDT hiding Measurement\n+open MIPStarRE.Quantum\n+open DistanceCalculus\n+\n+noncomputable section\n+\n+/-- The pointwise consistency defect of two direct coefficient measurements\n+after evaluating both coefficient vectors at the parameter `t`. -/\n+noncomputable def directCoefficientEvaluationDefect\n+    {ιA ιB : Type*}\n+    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n+    (D : DirectLdParams) (degree : ℕ)\n+    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA)\n+    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB)\n+    (ψ : EuclideanSpace ℂ (ιA × ιB))\n+    (line : DirectLineDesc D) (t : DirectScalarQ D) : Error :=\n+  ∑ a : DirectScalarQ D, ∑ b : DirectScalarQ D, if a = b then 0 else\n+    stateQForm ψ\n+      (heteroKron\n+        (((A line).postprocess\n+          (fun coefficients => evalCoefficient coefficients t)).effect a)\n+        (((B line).postprocess\n+          (fun coefficients => evalCoefficient coefficients t)).effect b))\n+\n+/-- The evaluated coefficient defect as a function of a joint direct\n+line-point sample. For a zero direction the point is independent of the\n+uniform affine parameter, so this definition retains that entire average\n+rather than selecting a distinguished parameter. -/\n+noncomputable def directJointCoefficientEvaluationDefect\n+    {ιA ιB : Type*}\n+    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n+    (D : DirectLdParams) (degree : ℕ)\n+    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA)\n+    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB)\n+    (ψ : EuclideanSpace ℂ (ιA × ιB))\n+    (sample : DirectLineDesc D × (Fin D.m → DirectScalarQ D)) : Error :=\n+  if sample.1.direction = 0 then\n+    avgOver (uniformDistribution (DirectScalarQ D))\n+      (fun t => directCoefficientEvaluationDefect D degree A B ψ sample.1 t)\n+  else\n+    directCoefficientEvaluationDefect D degree A B ψ sample.1\n+      (directLineRepParameter sample.1.direction sample.2)\n+\n+private theorem directLineRepParameter_base_add_smul\n+    (D : DirectLdParams) (line : DirectLineDesc D)\n+    (hdir : line.direction ≠ 0) (t : DirectScalarQ D) :\n+    directLineRepParameter line.direction\n+        (line.base + t • line.direction) = t := by\n+  apply directLineRepParameter_eq_of_nonzero hdir\n+  rw [lineRepMap_add_smul, line.base_fixed]\n+\n+private theorem avgOver_directJointCoefficientEvaluationDefect_affine\n+    {ιA ιB : Type*}\n+    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n+    (D : DirectLdParams) (degree : ℕ)\n+    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA)\n+    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB)\n+    (ψ : EuclideanSpace ℂ (ιA × ιB)) (line : DirectLineDesc D) :\n+    avgOver (uniformDistribution (DirectScalarQ D))\n+        (fun t => directCoefficientEvaluationDefect D degree A B ψ line t) =\n+      avgOver (uniformDistribution (DirectScalarQ D)) (fun t =>\n+        directJointCoefficientEvaluationDefect D degree A B ψ\n+          (line, line.base + t • line.direction)) := by\n+  by_cases hdir : line.direction = 0\n+  · simp [directJointCoefficientEvaluationDefect, hdir, avgOver_uniform_const]\n+  · apply avgOver_congr\n+    intro t\n+    simp [directJointCoefficientEvaluationDefect, hdir,\n+      directLineRepParameter_base_add_smul D line hdir t]\n+\n+/-- Uniform parameter evaluation over the axis-line marginal is exactly the\n+joint axis-line/point expectation of the corresponding coefficient defect. -/\n+theorem avgOver_directALinePointDist_coefficientEvaluation\n+    {ιA ιB : Type*}\n+    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n+    (D : DirectLdParams) (degree : ℕ)\n+    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA)\n+    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB)\n+    (ψ : EuclideanSpace ℂ (ιA × ιB)) :\n+    avgOver ((directALinePointDist D).map Prod.fst) (fun line =>\n+        avgOver (uniformDistribution (DirectScalarQ D))\n+          (fun t => directCoefficientEvaluationDefect D degree A B ψ line t)) =\n+      avgOver (directALinePointDist D)\n+        (directJointCoefficientEvaluationDefect D degree A B ψ) := by\n+  calc\n+    _ = avgOver ((directALinePointDist D).map Prod.fst) (fun line =>\n+        avgOver (uniformDistribution (DirectScalarQ D)) (fun t =>\n+          directJointCoefficientEvaluationDefect D degree A B ψ\n+            (line, line.base + t • line.direction))) := by\n+      apply avgOver_congr\n+      exact avgOver_directJointCoefficientEvaluationDefect_affine D degree A B ψ\n+    _ = _ := avgOver_directALinePointDist_resample D\n+      (directJointCoefficientEvaluationDefect D degree A B ψ)\n+\n+/-- Uniform parameter evaluation over the diagonal-line marginal is exactly\n+the joint diagonal-line/point expectation of the corresponding coefficient\n+defect, including zero-direction samples. -/\n+theorem avgOver_directDLinePointDist_coefficientEvaluation\n+    {ιA ιB : Type*}\n+    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n+    (D : DirectLdParams) (degree : ℕ)\n+    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA)\n+    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB)\n+    (ψ : EuclideanSpace ℂ (ιA × ιB)) :\n+    avgOver ((directDLinePointDist D).map Prod.fst) (fun line =>\n+        avgOver (uniformDistribution (DirectScalarQ D))\n+          (fun t => directCoefficientEvaluationDefect D degree A B ψ line t)) =\n+      avgOver (directDLinePointDist D)\n+        (directJointCoefficientEvaluationDefect D degree A B ψ) := by\n+  calc\n+    _ = avgOver ((directDLinePointDist D).map Prod.fst) (fun line =>\n+        avgOver (uniformDistribution (DirectScalarQ D)) (fun t =>\n+          directJointCoefficientEvaluationDefect D degree A B ψ\n+            (line, line.base + t • line.direction))) := by\n+      apply avgOver_congr\n+      exact avgOver_directJointCoefficientEvaluationDefect_affine D degree A B ψ\n+    _ = _ := avgOver_directDLinePointDist_resample D\n+      (directJointCoefficientEvaluationDefect D degree A B ψ)\n+\n+/-- The product-law consistency defect of evaluated direct coefficient POVMs\n+over axis lines is the corresponding original joint line-point expectation. -/\n+theorem consistencyDefect_directALine_coefficients_evaluated_eq_joint\n+    {ιA ιB : Type*}\n+    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n+    (D : DirectLdParams) (degree : ℕ)\n+    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA)\n+    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB)\n+    (ψ : EuclideanSpace ℂ (ιA × ιB)) :\n+    consistencyDefect\n+        (Distribution.prod ((directALinePointDist D).map Prod.fst)\n+          (uniformDistribution (DirectScalarQ D)))\n+        (fun lt value => heteroKron\n+          (((A lt.1).postprocess\n+            (fun coefficients => evalCoefficient coefficients lt.2)).effect value) 1)\n+        (fun lt value => heteroKron 1\n+          (((B lt.1).postprocess\n+            (fun coefficients => evalCoefficient coefficients lt.2)).effect value)) ψ =\n+      avgOver (directALinePointDist D)\n+        (directJointCoefficientEvaluationDefect D degree A B ψ) := by\n+  rw [SandwichProduct.consistencyDefect_placed_eq_avg_point,\n+    SandwichProduct.avgOver_distribution_prod]\n+  exact avgOver_directALinePointDist_coefficientEvaluation D degree A B ψ\n+\n+/-- The product-law consistency defect of evaluated direct coefficient POVMs\n+over diagonal lines is the corresponding original joint line-point\n+expectation, including zero-direction samples. -/\n+theorem consistencyDefect_directDLine_coefficients_evaluated_eq_joint\n+    {ιA ιB : Type*}\n+    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n+    (D : DirectLdParams) (degree : ℕ)\n+    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA)\n+    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB)\n+    (ψ : EuclideanSpace ℂ (ιA × ιB)) :\n+    consistencyDefect\n+        (Distribution.prod ((directDLinePointDist D).map Prod.fst)\n+          (uniformDistribution (DirectScalarQ D)))\n+        (fun lt value => heteroKron\n+          (((A lt.1).postprocess\n+            (fun coefficients => evalCoefficient coefficients lt.2)).effect value) 1)\n+        (fun lt value => heteroKron 1\n+          (((B lt.1).postprocess\n+            (fun coefficients => evalCoefficient coefficients lt.2)).effect value)) ψ =\n+      avgOver (directDLinePointDist D)\n+        (directJointCoefficientEvaluationDefect D degree A B ψ) := by\n+  rw [SandwichProduct.consistencyDefect_placed_eq_avg_point,\n+    SandwichProduct.avgOver_distribution_prod]\n+  exact avgOver_directDLinePointDist_coefficientEvaluation D degree A B ψ\n+\n+/-- Coefficient consistency over the axis-line marginal is bounded by its\n+original joint line-point evaluation defect plus `degree / q`. -/\n+theorem consistencyDefect_directALine_coefficients_le_joint_add\n+    {ιA ιB : Type*}\n+    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n+    (D : DirectLdParams) (degree : ℕ)\n+    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA)\n+    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB)\n+    (ψ : EuclideanSpace ℂ (ιA × ιB)) (hψ : ‖ψ‖ = 1) :\n+    consistencyDefect ((directALinePointDist D).map Prod.fst)\n+        (fun line coefficients => heteroKron ((A line).effect coefficients) 1)\n+        (fun line coefficients => heteroKron 1 ((B line).effect coefficients)) ψ ≤\n+      avgOver (directALinePointDist D)\n+          (directJointCoefficientEvaluationDefect D degree A B ψ) +\n+        (degree : ℝ) / (D.q : ℝ) := by\n+  have h := consistencyDefect_directCoefficients_le_evaluated_add\n+    D degree ((directALinePointDist D).map Prod.fst) A B ψ\n+    ((directALinePointDist_isProbability D).map Prod.fst) hψ\n+  rw [consistencyDefect_directALine_coefficients_evaluated_eq_joint\n+    D degree A B ψ] at h\n+  exact h\n+\n+/-- Coefficient consistency over the diagonal-line marginal is bounded by its\n+original joint line-point evaluation defect plus `degree / q`, with no\n+nonzero-direction restriction. -/\n+theorem consistencyDefect_directDLine_coefficients_le_joint_add\n+    {ιA ιB : Type*}\n+    [Fintype ιA] [DecidableEq ιA] [Fintype ιB] [DecidableEq ιB]\n+    (D : DirectLdParams) (degree : ℕ)\n+    (A : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιA)\n+    (B : DirectLineDesc D → Measurement (DirectDegPoly D degree) ιB)\n+    (ψ : EuclideanSpace ℂ (ιA × ιB)) (hψ : ‖ψ‖ = 1) :\n+    consistencyDefect ((directDLinePointDist D).map Prod.fst)\n+        (fun line coefficients => heteroKron ((A line).effect coefficients) 1)\n+        (fun line coefficients => heteroKron 1 ((B line).effect coefficients)) ψ ≤\n+      avgOver (directDLinePointDist D)\n+          (directJointCoefficientEvaluationDefect D degree A B ψ) +\n+        (degree : ℝ) / (D.q : ℝ) := by\n+  have h := consistencyDefect_directCoefficients_le_evaluated_add\n+    D degree ((directDLinePointDist D).map Prod.fst) A B ψ\n+    ((directDLinePointDist_isProbability D).map Prod.fst) hψ\n+  rw [consistencyDefect_directDLine_coefficients_evaluated_eq_joint\n+    D degree A B ψ] at h\n+  exact h\n+\n+end\n+\n+end MIPStarRE.QPBT\ndiff --git a/MIPStarRE/QPBT/Combining/ExtendedLineGame/DiagonalParameterDefectTransport.lean b/MIPStarRE/QPBT/Combining/ExtendedLineGame/DiagonalParameterDefectTransport.lean\nnew file mode 100644\nindex 00000000..12a9f33a\n--- /dev/null\n+++ b/MIPStarRE/QPBT/Combining/ExtendedLineGame/DiagonalParameterDefectTransport.lean\n@@ -0,0 +1,159 @@\n+import MIPStarRE.QPBT.Combining.ExtendedLineGame.ParameterEvaluatedLineBound\n+import MIPStarRE.QPBT.Combining.ExtendedLineGame.SameLineCoefficientBound\n+import MIPStarRE.QPBT.Observables.WinImplications.Averages\n+\n+/-!\n+# Transport for the diagonal parameter defect\n+\n+This module identifies the diagonal coefficient defect used in the same-line\n+rejection bound with the diagonal parameter-evaluation defect used in the\n+supplied-line comparison. The proof composes the measurement postprocessings\n+and uses `diagonalRead_eval` to compare the two coefficient readers.\n+\n+The equality is a formalization-only bridge supporting the classical-game\n+construction in the proof of `lem:qld-4-7`. It retains the original diagonal\n+line marginal, including zero directions, and introduces no new hypotheses.\n+\n+## References\n+\n+- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1020-1034`\n+- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1279-1288`\n+- Blueprint `lem:qld-4-7`.\n+- Issue #353.\n+-/\n+\n+namespace MIPStarRE.QPBT\n+\n+open MIPStarRE.LDT hiding Measurement\n+open MIPStarRE.Quantum\n+\n+noncomputable section\n+\n+namespace ExtendedLineGame\n+\n+variable {P : AdmissibleParams} {epsilon deltaQ deltaL : Real}\n+variable {setting : ProjectiveSetting P epsilon}\n+variable {points : CombinedPointsWitness setting deltaQ}\n+\n+/-- The independently evaluated diagonal coefficient defect equals the\n+diagonal parameter-evaluation defect of the direct-game strategy. -/\n+theorem diagonal_parameter_evaluated_coefficient_defect_eq\n+    (lines : ExtendedLinesWitness setting points deltaL) :\n+    diagonalParameterEvaluatedCoefficientDefect lines =\n+      diagonalParameterEvaluationDefect lines := by\n+  classical\n+  let readDiagonal : DirectLdAnswer P.extendedDirectLd →\n+      DirectDegPoly P.extendedDirectLd\n+        (P.extendedDirectLd.m * P.extendedDirectLd.d) := fun answer =>\n+    match answer with\n+    | .dlinePolys coefficients => coefficients ⟨0, by change 0 < 1; decide⟩\n+    | _ => 0\n+  let μ := Distribution.prod (uniformDistribution (DirectLdSpace P.extendedDirectLd))\n+    (uniformDistribution (DirectScalarQ P.extendedDirectLd))\n+  have hmeasurement :\n+      diagonalParameterEvaluatedCoefficientDefect lines =\n+        consistencyDefect μ\n+          (fun sample value => heteroKron\n+            (((answerMeasurement lines .alice\n+              (.dline, directLdMap P.extendedDirectLd .dline sample.1)).postprocess\n+                (fun answer => evalCoefficient (readDiagonal answer) sample.2)).effect value) 1)\n+          (fun sample value => heteroKron 1\n+            (((answerMeasurement lines .bob\n+              (.dline, directLdMap P.extendedDirectLd .dline sample.1)).postprocess\n+                (fun answer => evalCoefficient (readDiagonal answer) sample.2)).effect value))\n+          (pairState setting) := by\n+    unfold diagonalParameterEvaluatedCoefficientDefect consistencyDefect\n+    dsimp only [μ]\n+    simp only [SandwichProduct.avgOver_distribution_prod, directDLinePointDist,\n+      Distribution.map_map, Distribution.avgOver_map]\n+    apply avgOver_congr\n+    intro sample\n+    apply avgOver_congr\n+    intro parameter\n+    have hA (value : DirectScalarQ P.extendedDirectLd) :\n+        heteroKron\n+            (((lines.Qline .alice\n+              (directDLineDescOf P.extendedDirectLd sample)).postprocess\n+                (fun coefficients =>\n+                  evalCoefficient (diagonalRead P coefficients) parameter)).effect value)\n+            (1 : Op (setting.ExpandedLocalSpace .bob)) =\n+          heteroKron\n+            (((answerMeasurement lines .alice\n+              (.dline, directLdMap P.extendedDirectLd .dline sample)).postprocess\n+                (fun answer => evalCoefficient (readDiagonal answer) parameter)).effect value)\n+            1 := by\n+      apply congrArg (fun effect => heteroKron effect 1)\n+      unfold answerMeasurement\n+      rw [diagonal_description_canonical]\n+      rw [SandwichProduct.postprocess_postprocess_effect]\n+      apply congrArg (fun read =>\n+        ((lines.Qline .alice\n+          (directDLineDescOf P.extendedDirectLd sample)).postprocess read).effect value)\n+      funext coefficients\n+      calc\n+        evalCoefficient (diagonalRead P coefficients) parameter =\n+            evalCoefficient coefficients parameter :=\n+          diagonalRead_eval P coefficients parameter\n+        _ = evalCoefficient (readDiagonal (diagonalAnswer P coefficients)) parameter := by\n+          rw [show readDiagonal (diagonalAnswer P coefficients) =\n+            diagonalRead P coefficients by rfl]\n+          exact (diagonalRead_eval P coefficients parameter).symm\n+    have hB (value : DirectScalarQ P.extendedDirectLd) :\n+        heteroKron (1 : Op (setting.ExpandedLocalSpace .alice))\n+            (((lines.Qline .bob\n+              (directDLineDescOf P.extendedDirectLd sample)).postprocess\n+                (fun coefficients =>\n+                  evalCoefficient (diagonalRead P coefficients) parameter)).effect value) =\n+          heteroKron (1 : Op (setting.ExpandedLocalSpace .alice))\n+            (((answerMeasurement lines .bob\n+              (.dline, directLdMap P.extendedDirectLd .dline sample)).postprocess\n+                (fun answer => evalCoefficient (readDiagonal answer) parameter)).effect value) := by\n+      apply congrArg (fun effect => heteroKron 1 effect)\n+      unfold answerMeasurement\n+      rw [diagonal_description_canonical]\n+      rw [SandwichProduct.postprocess_postprocess_effect]\n+      apply congrArg (fun read =>\n+        ((lines.Qline .bob\n+          (directDLineDescOf P.extendedDirectLd sample)).postprocess read).effect value)\n+      funext coefficients\n+      calc\n+        evalCoefficient (diagonalRead P coefficients) parameter =\n+            evalCoefficient coefficients parameter :=\n+          diagonalRead_eval P coefficients parameter\n+        _ = evalCoefficient (readDiagonal (diagonalAnswer P coefficients)) parameter := by\n+          rw [show readDiagonal (diagonalAnswer P coefficients) =\n+            diagonalRead P coefficients by rfl]\n+          exact (diagonalRead_eval P coefficients parameter).symm\n+    apply Finset.sum_congr rfl\n+    intro valueA _\n+    apply Finset.sum_congr rfl\n+    intro valueB _\n+    simp only [SandwichProduct.postprocess_postprocess_effect]\n+    rw [hA valueA, hB valueB]\n+  rw [hmeasurement]\n+  change consistencyDefect μ\n+      (fun sample value => heteroKron\n+        ((((strategy lines).A\n+          (.dline, directLdMap P.extendedDirectLd .dline sample.1)).postprocess\n+            (fun answer => evalCoefficient (readDiagonal answer) sample.2)).effect value) 1)\n+      (fun sample value => heteroKron 1\n+        ((((strategy lines).B\n+          (.dline, directLdMap P.extendedDirectLd .dline sample.1)).postprocess\n+            (fun answer => evalCoefficient (readDiagonal answer) sample.2)).effect value))\n+      (strategy lines).ψ = diagonalParameterEvaluationDefect lines\n+  rw [WinImplications.consistencyDefect_postprocess_eq_mismatch]\n+  unfold diagonalParameterEvaluationDefect parameterEvalDefect\n+  simp only [directDLinePointDist, Distribution.avgOver_map]\n+  dsimp only [μ]\n+  rw [SandwichProduct.avgOver_distribution_prod]\n+  apply avgOver_congr\n+  intro sample\n+  apply avgOver_congr\n+  intro parameter\n+  rfl\n+\n+end ExtendedLineGame\n+\n+end\n+\n+end MIPStarRE.QPBT\ndiff --git a/MIPStarRE/QPBT/Combining/ExtendedLineGame/EvaluatedLineComparison.lean b/MIPStarRE/QPBT/Combining/ExtendedLineGame/EvaluatedLineComparison.lean\nindex 18ecd66f..1af51023 100644\n--- a/MIPStarRE/QPBT/Combining/ExtendedLineGame/EvaluatedLineComparison.lean\n+++ b/MIPStarRE/QPBT/Combining/ExtendedLineGame/EvaluatedLineComparison.lean\n@@ -35,17 +35,6 @@ variable {P : AdmissibleParams} {epsilon deltaQ deltaL : ℝ}\n variable {setting : ProjectiveSetting P epsilon}\n variable {points : CombinedPointsWitness setting deltaQ}\n \n-/-- Decompose a direct sample with its point first, retaining the jointly\n-uniform index and direction as the second coordinate. -/\n-private def directSamplePointEquiv (D : DirectLdParams) :\n-    DirectLdSpace D ≃\n-      (Fin D.m → DirectScalarQ D) ×\n-        (Fin D.m × (Fin D.m → DirectScalarQ D)) where\n-  toFun sample := (sample.point, sample.index, sample.direction)\n-  invFun sample := ⟨sample.1, sample.2.1, sample.2.2⟩\n-  left_inv sample := by cases sample; rfl\n-  right_inv sample := by cases sample; rfl\n-\n /-- A uniform consistency defect whose integrand uses only the first\n coordinate of a product equivalence has the corresponding uniform marginal. -/\n private theorem consistencyDefect_uniform_equiv_fst\n@@ -166,7 +155,7 @@ private theorem point_read_defect_on_direct_samples_eq_rejection\n           (Fin P.extendedDirectLd.m → DirectScalarQ P.extendedDirectLd))\