ExtendedLineGame\n+\n+variable {P : AdmissibleParams} {epsilon deltaQ deltaL : Real}\n+variable {setting : ProjectiveSetting P epsilon}\n+variable {points : CombinedPointsWitness setting deltaQ}\n+\n+/-- The sum of the seven potentially rejecting branches of the supplied\n+strategy is bounded by the scalar expression used by the direct passing-error\n+envelope. -/\n+theorem seven_branch_rejections_le\n+    (lines : ExtendedLinesWitness setting points deltaL) :\n+    directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.point, .point) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.point, .aline) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.point, .dline) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.aline, .point) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.aline, .aline) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.dline, .point) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.dline, .dline) ≤\n+      deltaQ + 16 * deltaL + 4 * Real.sqrt (deltaQ + 2 * deltaL) +\n+        5 * ((P.m * P.d : Real) / (P.q : Real)) := by\n+  have hpoint := point_point_rejection_le lines\n+  have hmixed := mixed_line_point_rejections_le_four_mul lines\n+  have haxis :=\n+    aline_aline_rejection_le_axisParameterEvaluatedCoefficientDefect_add lines\n+  have hdiagonal :=\n+    dline_dline_rejection_le_diagonalParameterEvaluatedCoefficientDefect_add lines\n+  rw [axis_parameter_evaluated_coefficient_defect_eq] at haxis\n+  rw [diagonal_parameter_evaluated_coefficient_defect_eq] at hdiagonal\n+  have haxisEval := axis_parameter_evaluation_defect_le lines\n+  have hdiagonalEval := diagonal_parameter_evaluation_defect_le lines\n+  have hcollision :\n+      (P.d : Real) / (P.extendedDirectLd.q : Real) +\n+          (P.extendedDirectLd.m * P.extendedDirectLd.d : Real) /\n+            (P.extendedDirectLd.q : Real) ≤\n+        5 * ((P.m * P.d : Real) / (P.q : Real)) := by\n+    calc\n+      _ = ((P.extendedDirectLd.d : Real) +\n+            (P.extendedDirectLd.m * P.extendedDirectLd.d : Real)) /\n+          (P.extendedDirectLd.q : Real) := by\n+        change\n+          (P.extendedDirectLd.d : Real) / (P.extendedDirectLd.q : Real) +\n+              (P.extendedDirectLd.m * P.extendedDirectLd.d : Real) /\n+                (P.extendedDirectLd.q : Real) = _\n+        ring\n+      _ ≤ _ := extendedDirectLd_coefficientCollisionLoss_le_five_mul P\n+  linarith\n+\n+/-- The supplied directly indexed strategy passes with error bounded by the\n+concrete polynomial envelope in `deltaQ + deltaL` and `m*d/q`. -/\n+theorem strategy_value_ge_directPassingErrorEnvelope\n+    (lines : ExtendedLinesWitness setting points deltaL) :\n+    1 - directPassingErrorEnvelope (deltaQ + deltaL)\n+        ((P.m * P.d : Real) / (P.q : Real)) ≤\n+      (strategy lines).value := by\n+  let rejection :=\n+    directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.point, .point) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.point, .aline) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.point, .dline) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.aline, .point) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.aline, .aline) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.dline, .point) +\n+        directLdBranchRejectionProbability P.extendedDirectLd (strategy lines)\n+          (.dline, .dline)\n+  have hsum : rejection ≤\n+      deltaQ + 16 * deltaL + 4 * Real.sqrt (deltaQ + 2 * deltaL) +\n+        5 * ((P.m * P.d : Real) / (P.q : Real)) := by\n+    exact seven_branch_rejections_le lines\n+  have hcap : rejection / 9 ≤ 1 := by\n+    have h := directLdRejectionProbability_le_one P.extendedDirectLd (strategy lines)\n+    rw [directLdRejectionProbability_eq_one_sub_value, strategy_value_eq lines] at h\n+    change rejection / 9 ≤ 1\n+    linarith\n+  have hraw : rejection / 9 ≤\n+      (deltaQ + 16 * deltaL + 4 * Real.sqrt (deltaQ + 2 * deltaL) +\n+        5 * ((P.m * P.d : Real) / (P.q : Real))) / 9 := by\n+    linarith\n+  have henvelope := seven_branch_capped_error_le_directPassingErrorEnvelope\n+    deltaQ deltaL ((P.m * P.d : Real) / (P.q : Real))\n+    points.delta_nonneg lines.delta_nonneg (by positivity)\n+  have hrejection : rejection / 9 ≤\n+      directPassingErrorEnvelope (deltaQ + deltaL)\n+        ((P.m * P.d : Real) / (P.q : Real)) :=\n+    (le_min hcap hraw).trans henvelope\n+  rw [strategy_value_eq lines]\n+  change 1 - _ ≤ 1 - rejection / 9\n+  linarith\n+\n+/-- The Naimark-projectivized supplied strategy has the same passing-value\n+lower bound as the original strategy. -/\n+theorem projectiveStrategy_value_ge_directPassingErrorEnvelope\n+    (lines : ExtendedLinesWitness setting points deltaL) :\n+    1 - directPassingErrorEnvelope (deltaQ + deltaL)\n+        ((P.m * P.d : Real) / (P.q : Real)) ≤\n+      (projectiveStrategy lines).value := by\n+  rw [projectiveStrategy_value]\n+  exact strategy_value_ge_directPassingErrorEnvelope lines\n+\n+end ExtendedLineGame\n+\n+end\n+\n+end MIPStarRE.QPBT\ndiff --git a/MIPStarRE/QPBT/Combining/PassingError.lean b/MIPStarRE/QPBT/Combining/PassingError.lean\nnew file mode 100644\nindex 00000000..b1c0d3dc\n--- /dev/null\n+++ b/MIPStarRE/QPBT/Combining/PassingError.lean\n@@ -0,0 +1,90 @@\n+import MIPStarRE.QPBT.Games.ErrorFunctions\n+\n+/-! # Capped scalar envelope for direct-game error bounds\n+\n+This module gives a concrete polynomial envelope for a scalar expression assembled from\n+seven prospective rejection bounds in the directly indexed extended-line game. It is a\n+formalization-only arithmetic auxiliary: it does not prove that any game branch satisfies\n+one of these bounds, nor does it prove a passing-value theorem.\n+\n+The cap by one records the independent fact that a rejection probability is at most one.\n+It is essential for the polynomial-error contract: the uncapped function\n+`2 * x + Real.sqrt x + y` cannot be bounded by one positive power of `x` both near zero\n+and at infinity.\n+\n+## References\n+\n+- `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:1279-1288`\n+- Parent issue #119 and arithmetic issue #326\n+-/\n+\n+namespace MIPStarRE.QPBT\n+\n+/-- The concrete two-variable polynomial envelope for the capped scalar bound. -/\n+noncomputable def directPassingErrorEnvelope (x y : ℝ) : ℝ :=\n+  3 * (Real.sqrt x + y)\n+\n+/-- The direct passing-error envelope obeys the shared two-variable polynomial-error\n+contract, with prefactor `3` and exponents `1 / 2` and `1`. -/\n+theorem directPassingErrorEnvelope_isPolyErr₂ : IsPolyErr₂ directPassingErrorEnvelope := by\n+  refine ⟨3, 1 / 2, 1, by norm_num, by norm_num, by norm_num, ?_⟩\n+  intro x y hx hy\n+  constructor\n+  · exact mul_nonneg (by norm_num) (add_nonneg (Real.sqrt_nonneg x) hy)\n+  · simp [directPassingErrorEnvelope, Real.sqrt_eq_rpow]\n+\n+/-- A positive second input makes the direct passing-error envelope positive. -/\n+theorem directPassingErrorEnvelope_pos (x y : ℝ) (hy : 0 < y) :\n+    0 < directPassingErrorEnvelope x y := by\n+  dsimp [directPassingErrorEnvelope]\n+  nlinarith [Real.sqrt_nonneg x]\n+\n+/-- The proposed seven-term scalar error is bounded by nine times the uncapped\n+linear-square-root expression. The variables are only nonnegative real numbers here;\n+no game-level branch estimate is asserted. -/\n+theorem seven_branch_scalar_error_le (Q L r : ℝ) (hQ : 0 ≤ Q) (hL : 0 ≤ L)\n+    (hr : 0 ≤ r) :\n+    Q + 16 * L + 4 * Real.sqrt (Q + 2 * L) + 5 * r ≤\n+      9 * (2 * (Q + L) + Real.sqrt (Q + L) + r) := by\n+  have hQL : 0 ≤ Q + L := by linarith\n+  have hQ2L : 0 ≤ Q + 2 * L := by linarith\n+  have hroot : Real.sqrt (Q + 2 * L) ≤ 2 * Real.sqrt (Q + L) := by\n+    nlinarith [Real.sq_sqrt hQL, Real.sq_sqrt hQ2L,\n+      Real.sqrt_nonneg (Q + L), Real.sqrt_nonneg (Q + 2 * L)]\n+  nlinarith [Real.sqrt_nonneg (Q + L)]\n+\n+private theorem min_linear_sqrt_le_directPassingErrorEnvelope (x y : ℝ)\n+    (hx : 0 ≤ x) (hy : 0 ≤ y) :\n+    min 1 (2 * x + Real.sqrt x + y) ≤ directPassingErrorEnvelope x y := by\n+  by_cases hxOne : x ≤ 1\n+  · have hsqrtOne : Real.sqrt x ≤ 1 := by\n+      simpa using Real.sqrt_le_sqrt hxOne\n+    have hxSqrt : x ≤ Real.sqrt x := by\n+      nlinarith [Real.sq_sqrt hx, Real.sqrt_nonneg x]\n+    exact (min_le_right _ _).trans (by\n+      dsimp [directPassingErrorEnvelope]\n+      nlinarith)\n+  · have hsqrtOne : 1 ≤ Real.sqrt x := by\n+      have hxOne' : 1 ≤ x := le_of_not_ge hxOne\n+      simpa using Real.sqrt_le_sqrt hxOne'\n+    exact (min_le_left _ _).trans (by\n+      dsimp [directPassingErrorEnvelope]\n+      nlinarith [Real.sqrt_nonneg x])\n+\n+/-- After averaging the seven scalar contributions by the nine equally weighted game\n+branches and applying the probability cap, the result is bounded by the concrete\n+polynomial envelope. This theorem assumes only the displayed nonnegative scalar inputs;\n+it does not establish the unfinished branch bounds that would supply them. -/\n+theorem seven_branch_capped_error_le_directPassingErrorEnvelope\n+    (Q L r : ℝ) (hQ : 0 ≤ Q) (hL : 0 ≤ L) (hr : 0 ≤ r) :\n+    min 1 ((Q + 16 * L + 4 * Real.sqrt (Q + 2 * L) + 5 * r) / 9) ≤\n+      directPassingErrorEnvelope (Q + L) r := by\n+  have hraw := seven_branch_scalar_error_le Q L r hQ hL hr\n+  have hdiv :\n+      (Q + 16 * L + 4 * Real.sqrt (Q + 2 * L) + 5 * r) / 9 ≤\n+        2 * (Q + L) + Real.sqrt (Q + L) + r := by\n+    nlinarith\n+  exact (min_le_min_left 1 hdiv).trans\n+    (min_linear_sqrt_le_directPassingErrorEnvelope (Q + L) r (by linarith) hr)\n+\n+end MIPStarRE.QPBT\ndiff --git a/MIPStarRE/QPBT/Combining/Witnesses.lean b/MIPStarRE/QPBT/Combining/Witnesses.lean\nindex 985ce3bd..916d74d5 100644\n--- a/MIPStarRE/QPBT/Combining/Witnesses.lean\n+++ b/MIPStarRE/QPBT/Combining/Witnesses.lean\n@@ -51,45 +51,6 @@ def directPointToPauli (P : AdmissibleParams)\n     Fin (2 * P.m + 2) -> PauliScalar P :=\n   fun i => extendedDirectScalarEquiv P (u i)\n \n-/-! ## Finite direct-line carrier -/\n-\n-/-- A finite code for directly indexed lines, omitting only proof fields. -/\n-private abbrev DirectLineDescCode (D : DirectLdParams) :=\n-  ((Fin D.m -> DirectScalarQ D) × Fin D.m) ⊕\n-    ((Fin D.m -> DirectScalarQ D) × Fin D.m ×\n-      (Fin D.m -> DirectScalarQ D))\n-\n-/-- Encode a directly indexed line by its tag and mathematical data. -/\n-private def directLineDescCode (D : DirectLdParams) :\n-    DirectLineDesc D -> DirectLineDescCode D\n-  | .axis base index _ => .inl (base, index)\n-  | .diagonal base index direction _ _ => .inr (base, index, direction)\n-\n-/-- The direct-line code is injective by proof irrelevance. -/\n-private theorem directLineDescCode_injective (D : DirectLdParams) :\n-    Function.Injective (directLineDescCode D) := by\n-  intro line line' h\n-  cases line with\n-  | axis base index baseFixed =>\n-      cases line' with\n-      | axis base' index' baseFixed' =>\n-          simp only [directLineDescCode, Sum.inl.injEq, Prod.mk.injEq] at h\n-          rcases h with ⟨rfl, rfl⟩\n-          rfl\n-      | diagonal => simp [directLineDescCode] at h\n-  | diagonal base index direction baseFixed prefixZero =>\n-      cases line' with\n-      | axis => simp [directLineDescCode] at h\n-      | diagonal base' index' direction' baseFixed' prefixZero' =>\n-          simp only [directLineDescCode, Sum.inr.injEq, Prod.mk.injEq] at h\n-          rcases h with ⟨rfl, rfl, rfl⟩\n-          rfl\n-\n-/-- Directly indexed line descriptions form a finite type. -/\n-noncomputable instance directLineDescFintype (D : DirectLdParams) :\n-    Fintype (DirectLineDesc D) :=\n-  Fintype.ofInjective (directLineDescCode D) (directLineDescCode_injective D)\n-\n /-! ## Combined point and line measurements -/\n \n /-- Projective joint point measurements and their ordered consistency\n","exit_code":0,"status":"completed"}}
