ide) +    (lineX lineZ : LineDesc P.toLdParams) : +    Quantum.Measurement (DegPoly P.toLdParams (P.m * P.d) × +      DegPoly P.toLdParams (P.m * P.d)) (S.ExpandedLocalSpace side) := +  Measurement.ofSumEqOne +    (fun fs => (S.lineMeasExp side .X lineX).effect fs.1 * +      (S.lineMeasExp side .Z lineZ).effect fs.2 * +      (S.lineMeasExp side .X lineX).effect fs.1) +    (fun fs => (pastedMeasurement_isMeasurement +      (S.lineMeasExp side .Z lineZ) (S.lineMeasExp side .X lineX) +      (S.lineMeasExp_isProjective side .X lineX)).1 (fs.2, fs.1)) +    (by +      classical +      have hsum := (pastedMeasurement_isMeasurement +        (S.lineMeasExp side .Z lineZ) (S.lineMeasExp side .X lineX) +        (S.lineMeasExp_isProjective side .X lineX)).2 +      simp only [pastedMeasurement, Fintype.sum_prod_type] at hsum ⊢ +      rw [Finset.sum_comm] +      exact hsum) + +/-- The effects of the paired-line POVM are the source's X-Z-X sandwiches. -/ +@[simp] theorem ProjectiveSetting.combinedLineMeasurement_effect +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (side : PlayerSide) +    (lineX lineZ : LineDesc P.toLdParams) +    (fX fZ : DegPoly P.toLdParams (P.m * P.d)) : +    (S.combinedLineMeasurement side lineX lineZ).effect (fX, fZ) = +      (S.lineMeasExp side .X lineX).effect fX * +        (S.lineMeasExp side .Z lineZ).effect fZ * +        (S.lineMeasExp side .X lineX).effect fX := rfl + +/-- The constructed X-outer sandwich is the one-sided pasting output with +`G1 = Z`, `G2 = X`, and the polynomial answers exchanged. This identity fixes +the orientation in paper `14_analysis_of_the_pauli_basis_test.tex:943-961`; +it asserts no unproved consistency relation. -/ +theorem ProjectiveSetting.combinedLineMeasurement_effect_eq_pastedMeasurement +    {P : AdmissibleParams} {ε : ℝ} (S : ProjectiveSetting P ε) (side : PlayerSide) +    (lineX lineZ : LineDesc P.toLdParams) +    (fX fZ : DegPoly P.toLdParams (P.m * P.d)) : +    (S.combinedLineMeasurement side line