ar P, ‖applyOperatorToState +        (S.place p₂ ((S.pointMeasExp p₂.side .X xz.1).effect ab.1 * +            (S.pointMeasExp p₂.side .Z xz.2).effect ab.2) - +          S.place p₂ ((S.pointMeasExp p₂.side .Z xz.2).effect ab.2 * +            (S.pointMeasExp p₂.side .X xz.1).effect ab.1)) S.psiHat‖ ^ 2) + +/-- The pointwise bound is nonnegative. -/ +theorem sandwichDefectBound_nonneg (S : ProjectiveSetting P ε) (p₁ p₂ : Placement) +    (xz : PointPair P) : 0 ≤ S.sandwichDefectBound p₁ p₂ xz := by +  unfold sandwichDefectBound +  positivity + +/-- For a fixed point pair, the off-diagonal mass of the two placed sandwiches +is at most the pointwise bound.  This is the consistency of the sandwich POVM +between opposite placements, display `eq:rw-sc` of the proof of +`lem:qld-4-10`, paper +`references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:743-790`, in +exact form. -/ +theorem sandwich_offDiagonal_le_sandwichDefectBound (S : ProjectiveSetting P ε) +    (p₁ p₂ : Placement) (hopp : p₁.IsOpposite p₂) (xz : PointPair P) : +    (∑ ab : PauliScalar P × PauliScalar P, ∑ ab' : PauliScalar P × PauliScalar P, +      if ab = ab' then 0 else stateQForm S.psiHat +        (S.place p₁ ((S.sandwichPoint p₁.side xz.1 xz.2).effect ab) * +          S.place p₂ ((S.sandwichPoint p₂.side xz.1 xz.2).effect ab'))) ≤ +      S.sandwichDefectBound p₁ p₂ xz := by +  have hdefect := point_defect_eq +    (S.placedMeasurement p₁ (S.sandwichPoint p₁.side xz.1 xz.2)) +    (S.placedMeasurement p₂ (S.sandwichPoint p₂.side xz.1 xz.2)) S.psiHat +  simp only [placedMeasurement_effect] at hdefect +  rw [hdefect, psiHat_norm] +  have hkey := sandwich_defect_pointwise_le S.psiHat +    (S.placedMeasurement p₁ (S.pointMeasExp p₁.side .X xz.1)) +    (S.placedMeasurement p₂ (S.pointMeasExp p₂.side .X xz.1)) +    (S.placedMeasurement p₁ (S.pointMeasExp p₁.side .Z xz.2)) +    (S.placedMeasurement p₂ (S.pointMeasExp p₂.side .Z xz.2)) +    (S.placedMeasurement_isProjective p₁ _ (S.pointMeasExp_isProjective _ _ _)) +    (S.placedMeasurement_isProjective p₂ _ (S.pointMeasExp_isProjective _ _ _)) +    (S.placedMeasurement_isProjective p₁ _ (S.pointMeasExp_isProjective _ _ _)) +    (S.placedMeasurement_isProjective p₂ _ (S.pointMeasExp_isProjective _ _ _)) +    (fun a b => S.place_comm p₁ p₂ hopp _ _) +    (fun a b => S.place_comm p₁ p₂ hopp _ _) +    (fun b => S.place_comm p₁ p₂ hopp _ _) +  simp only [placedMeasurement_effect, psiHat_norm] at hkey +  unfold sandwichDefectBound +  simp only [sandwichPoint_effect, place_mul] +  simpa only [place_mul] using hkey + +/-- The average over the point pair of the pointwise bound is polynomially +small: at most a universal constant times `ε + √ε`.  The `X`- and +`Z`-distances are the self-consistency of item 1 of `lem:qld-comm-cons`, and +the two commutator sums are the field-valued commutation estimate. -/ +theorem avg_sandwichDefectBound_le : +    ∃ C : ℝ, 1 ≤ C ∧ +      ∀ (P : AdmissibleParams) (ε : ℝ) (S : ProjectiveSetting P ε) +        (p₁ p₂ : Placement), p₁.IsOpposite p₂ → +        avgOver (uniformDistribution (PointPair P)) (S.sandwichDefectBound p₁ p₂) ≤ +          C * (ε + Real.sqrt ε) := by +  obtain ⟨C₁, hC₁, h₁⟩ := expPoint_self_cons +  obtain ⟨C₂, hC₂, h₂⟩ := expPoint_comm +  refine ⟨2 * C₁ + 3 * C₂, by linarith, ?_⟩ +  intro P ε S p₁ p₂ hopp +  have hε : (0 : ℝ) ≤ ε := by +    have hv := WinImplications.strategy_value_le_one S.toStrategy +    have hw := S.win +    linarith +  have hZ : avgOver (uniformDistribution (PointPair P)) (fun xz => +      ∑ b : PauliScalar P, ‖applyOperatorToState +        (S.place p₁ ((S.pointMeasExp p₁.side .Z xz.2).effect b) - +          S.place p₂ ((S.pointMeasExp p₂.side .Z xz.2).effect b)) S.psiHat‖ ^ 2) ≤ +      C₁ * ε := by +    rw [avgOver_uniform_snd (α := Fin P.m → PauliScalar P) +      (fun z => ∑ b : PauliScalar P, ‖applyOperatorToState +        (S.place p₁ ((S.pointMeasExp p₁.side .Z z).effect b) - +          S.place p₂ ((S.pointMeasExp p₂.side .Z z).effect b)) S.psiHat‖ ^ 2)] +    exact h₁ P ε S p₁ p₂ hopp .Z +  have hX : avgOver (uniformDistribution (PointPair P)) (fun xz => +      ∑ a : PauliScalar P, ‖applyOperatorToState +        (S.place p₁ ((S.pointMeasExp p₁.side .X xz.1).effect a) - +          S.place p₂ ((S.pointMeasExp p₂.side .X xz.1).effect a)) S.psiHat‖ ^ 2) ≤ +      C₁ * ε := by +    rw [avgOver_uniform_fst (β := Fin P.m → PauliScalar P) +      (fun x => ∑ a : PauliScalar P, ‖applyOperatorToState +        (S.place p₁ ((S.pointMeasExp p₁.side .X x).effect a) - +          S.place p₂ ((S.pointMeasExp p₂.side .X x).effect a)) S.psiHat‖ ^ 2)] +    exact h₁ P ε S p₁ p₂ hopp .X +  have hK₁ := h₂ P ε S p₁ +  have hK₂ := h₂ P ε S p₂ +  unfold opFamilyDistSq at hK₁ hK₂ +  unfold sandwichDefectBound +  rw [avgOver_add, avgOver_const_mul, avgOver_const_mul, avgOver_add, +    avgOver_add] +  have hs : (0 : ℝ) ≤ Real.sqrt ε := Real.sqrt_nonneg ε +  nlinarith [hZ, hX, hK₁, hK₂, hs, hε, hC₁, hC₂] + +end ProjectiveSetting + +end + +end MIPStarRE.QPBT diff --git a/MIPStarRE/QPBT/Combining/Points/Orthonormalization.lean b/MIPStarRE/QPBT/Combining/Points/Orthonormalization.lean new file mode 100644 index 00000000..a329eb37 --- /dev/null +++ b/MIPStarRE/QPBT/Combining/Points/Orthonormalization.lean @@ -0,0 +1,330 @@ +import MIPStarRE.QPBT.Combining.Points.Consistency +import MIPStarRE.QPBT.Games.DistanceTheorems + +/-! +# Orthonormalization of the sandwich POVM + +For each fixed point pair `(x, z)`, the sandwich POVM `R^{x,z}` on one +register placement is consistent with the sandwich POVM on the opposite +placement, with the consistency defect bounded by +`ProjectiveSetting.sandwichDefectBound`.  The orthonormalization lemma +`lem:ortho`, in its explicit-constant form +`projective_rounding_with_explicit_constant`, therefore produces a projective +measurement `Q^{x,z}` on the original local space, within `220 · c^{1/4}` of +`R^{x,z}` on the expanded state, where `c` is that bound.  Choosing such a +measurement for every pair and averaging, the concavity of `t ↦ t^{1/4}` +turns the average of the fiberwise errors into the same function of the +average defect. + +The orthonormalization lemma is stated for a bipartite state whose first +tensor factor carries the POVM to be rounded.  The two bipartitions used are +`AA' | BA''(B'B'')`, for Alice's measurements, and `BA'' | AA'(B'B'')`, for +Bob's; the second is introduced here. + +## Main results + +* `baAaBipartition` with its two placement lemmas. +* `avgOver_rpow_quarter_le`: Jensen's inequality for the fourth root. +* `ProjectiveSetting.exists_projective_close_sandwich`: the fiberwise +  orthonormalization, for any bipartition exhibiting the two placements as +  the two tensor factors. + +## References + +Paper `references/qpbt-paper/14_analysis_of_the_pauli_basis_test.tex:786-790` +(the application of the orthonormalization lemma), blueprint +`blueprint/src/chapter/ch15_qpbt_combining.tex:870-878` (`lem:qld-4-10`), and +`blueprint/src/chapter/ch14_qpbt_observables.tex:395-464` (`lem:ortho`); the +route is explained in `docs/paper-gaps/qpbt_linearity-theorem-quotation.tex`. +-/ + +open scoped BigOperators Matrix MatrixOrder ComplexOrder + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT hiding Measurement +open MIPStarRE.Quantum DistanceCalculus + +noncomputable section + +/-! ## Jensen's inequality for the fourth root -/ + +/-- The fourth root of a nonnegative real is the iterated square root. -/ +theorem rpow_quarter_eq_sqrt_sqrt {t : ℝ} (ht : 0 ≤ t) : +    Real.rpow t (1 / 4 : ℝ) = Real.sqrt (Real.sqrt t) := by +  rw [Real.sqrt_eq_rpow, Real.sqrt_eq_rpow, ← Real.rpow_mul ht] +  norm_num + +/-- Jensen's inequality for the concave function `t ↦ t^{1/4}` on a +sub-probability average, obtained by applying the square-root inequality +twice. -/ +theorem avgOver_rpow_quarter_le {X : Type*} (𝒟 : Distribution X) +    (h𝒟 : ∑ x ∈ 𝒟.support, 𝒟.weight x ≤ 1) (b : X → ℝ) (hb : ∀ x, 0 ≤ b x) : +    avgOver 𝒟 (fun x => Real.rpow (b x) (1 / 4 : ℝ)) ≤ +      Real.rpow (avgOver 𝒟 b) (1 / 4 : ℝ) := by +  have h1 : |avgOver 𝒟 (fun x => Real.sqrt (Real.sqrt (b x)))| ≤ +      Real.sqrt (avgOver 𝒟 (fun x => Real.sqrt (b x))) := +    MIPStarRE.LDT.Preliminaries.avgOver_abs_le_sqrt_of_pointwise 𝒟 _ _ +      (fun x => by rw [abs_of_nonneg (Real.sqrt_nonneg _)]) +      (fun x => Real.sqrt_nonneg _) h𝒟 +  have h2 : |avgOver 𝒟 (fun x => Real.sqrt (b x))| ≤ Real.sqrt (avgOver 𝒟 b) := +    MIPStarRE.LDT.Preliminaries.avgOver_abs_le_sqrt_of_pointwise 𝒟 _ _ +      (fun x => by rw [abs_of_nonneg (Real.sqrt_nonneg _)]) hb h𝒟 +  have havg : 0 ≤ avgOver 𝒟 b := avgOver_nonneg 𝒟 b hb +  rw [rpow_quarter_eq_sqrt_sqrt havg] +  calc avgOver 𝒟 (fun x => Real.rpow (b x) (1 / 4 : ℝ)) +      = avgOver 𝒟 (fun x => Real.sqrt (Real.sqrt (b x))) := +        avgOver_congr _ _ _ fun x => rpow_quarter_eq_sqrt_sqrt (hb x) +    _ ≤ |avgOver 𝒟 (fun x => Real.sqrt (Real.sqrt (b x)))| := le_abs_self _ +    _ ≤ Real.sqrt (avgOver 𝒟 (fun x => Real.sqrt (b x))) := h1 +    _ ≤ Real.sqrt (Real.sqrt (avgOver 𝒟 b)) := +        Real.sqrt_le_sqrt (le_trans (le_abs_self _) h2) + +/-! ## The bipartition with Bob's registers first -/ + +/-- Regroup `AA'A''BB'B''` as `BA'' | AA'(B'B'')`.  This is the bipartition +in which Bob's expanded local space is the first tensor factor, used to +orthonormalize the sandwich POVM on Bob's side. -/ +def baAaBipartition (P : AdmissibleParams) (ιA ιB : Type*) : +    SixReg P ιA ιB ≃ +      (ιB × PauliRegister P) × +        ((ιA × PauliRegister P) × (PauliRegister P × PauliRegister P)) where +  toFun := fun ⟨⟨a, a', a''⟩, b, b', b''⟩ => ((b, a''), ((a, a'), (b', b''))) +  invFun := fun ⟨⟨b, a''⟩, ⟨a, a'⟩, b', b''⟩ => ((a, (a', a'')), (b, (b', b''))) +  left_inv := by rintro ⟨⟨a, a', a''⟩, b, b', b''⟩; rfl +  right_inv := by rintro ⟨⟨b, a''⟩, ⟨a, a'⟩, b', b''⟩; rfl + +namespace ProjectiveSetting + +variable {P : AdmissibleParams} {ε : ℝ} + +/-- Under the `BA'' | AA'(B'B'')` bipartition, a `BA''` placement is the +ordinary left tensor placement. -/ +th