ompressAt_postprocess +    {A B I κ : Type*} +    [Fintype A] [DecidableEq A] [Fintype B] [DecidableEq B] +    [Fintype I] [DecidableEq I] [Fintype κ] [DecidableEq κ] +    (k₀ : κ) (M : MIPStarRE.Quantum.Measurement A (I × κ)) (f : A → B) : +    (M.postprocess f).compressAt k₀ = (M.compressAt k₀).postprocess f := by +  classical +  apply MIPStarRE.Quantum.Measurement.ext +  intro b +  ext i j +  simp only [compressAt_effect, MIPStarRE.Quantum.Measurement.postprocess_effect, +    Matrix.submatrix_apply, Matrix.sum_apply] + +end MIPStarRE.Quantum.Measurement + +namespace MIPStarRE.QPBT + +open MIPStarRE.LDT MIPStarRE.Quantum + +namespace Measurement + +/-- Compressing the completed one-measurement Naimark dilation at its +distinguished `none` coordinate recovers the original POVM. -/ +theorem compressAt_dilatedMeasurement +    {A I : Type} [Fintype A] [DecidableEq A] +    [Fintype I] [DecidableEq I] +    (a₀ : A) (M : MIPStarRE.Quantum.Measurement A I) : +    (dilatedMeasurement a₀ M).compressAt none = M := by +  apply MIPStarRE.Quantum.Measurement.ext +  intro a +  ext i j +  exact dilatedMeasurement_compression a₀ a M i j + +end Measurement + +/-- Ground-slice compression preserves exactly the off-diagonal consistency +defect when the bipartite state is padded at the same two ancillary +coordinates. This is an equality of POVM correlations and does not assert that +the compressed measurements are projective. -/ +theorem consistencyDefect_padState_compressAt +    {X Outcome I J κA κB : Type*} +    [Fintype X] [DecidableEq X] +    [Fintype Outcome] [DecidableEq Outcome] +    [Fintype I] [DecidableEq I] [Fintype J] [DecidableEq J] +    [Fintype κA] [DecidableEq κA] [Fintype κB] [DecidableEq κB] +    (μ : Distribution X) +    (MA : X → MIPStarRE.Quantum.Measurement Outcome (I × κA)) +    (MB : X → MIPStarRE.Quantum.Measurement Outcome (J × κB)) +    (a₀ : κA) (b₀ : κB) (ψ : EuclideanSpace ℂ (I × J)) : +    consistencyDefect μ +        (fun x a => heteroKron ((MA x).effe